#![cfg(feature="sqlite")]
use cyclecare_core::{local_commit_store::*,local_commit_plan::Identity,sync_codec as c};
fn id()->Identity{Identity{namespace:"A".into(),effective:"ea".into(),instance:"dba".into(),epoch:1,session:1,generation:0,local:true}}
fn log()->c::CycleDayLog{let mut l=cyclecare_core::track_log::CycleDayLog::new("2024-03-17");l.notes="all fields kept α".into();l.bbt_celsius=36.6;l.sleep_hours=7.3;(&l).into()}
#[test]
fn absent_settings_materialized_and_replay_precedes_occ(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();let p=s.prepare_save(&i,"op",&l).unwrap();assert!(s.settings().unwrap().is_none());let first=s.commit(&p).unwrap();assert!(matches!(first,Outcome::Committed{replay:false,..}));assert_eq!(s.settings().unwrap(),Some(c::CycleSettings::default()));assert_eq!(c::log_payload(&c::CycleDayLog::from(&s.log(&l.date).unwrap().unwrap())),c::log_payload(&l));assert!(matches!(s.commit(&p).unwrap(),Outcome::Committed{replay:true,..}));let mut changed=l.clone();changed.notes="different".into();let other=s.prepare_save(&i,"op",&changed).unwrap();assert_eq!(s.commit(&other),Err(Error::InvalidReuse));}
#[test]
fn first_anchor_and_all_fault_steps_atomic(){for fault in 1..=7{let i=id();let s=ScratchStore::new_memory(&i).unwrap();let mut l=log();l.flow="LIGHT".into();let p=s.prepare_save(&i,"op",&l).unwrap();assert_eq!(s.commit_fault_for_test(&p,fault,false),Err(Error::Storage));assert!(s.settings().unwrap().is_none());assert!(s.log(&l.date).unwrap().is_none());assert!(matches!(s.commit(&p).unwrap(),Outcome::Committed{replay:false,..}));assert_eq!(s.settings().unwrap().unwrap().last_period_start_date,l.date);assert!(matches!(s.commit(&p).unwrap(),Outcome::Committed{replay:true,..}));}}
#[test]
fn same_revision_domain_and_local_settings_drift_rejected(){
 let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();let p=s.prepare_save(&i,"seed",&l).unwrap();s.commit(&p).unwrap();
 for sql in ["UPDATE cycle_day_logs SET notes='bypass'", "UPDATE cycle_settings SET isAppLockEnabled=1", "UPDATE cycle_settings SET averageCycleLength=30"]{let p=s.prepare_save(&i,sql,&l).unwrap();s.inject_sql_for_test(sql).unwrap();assert_eq!(s.commit(&p),Err(Error::Conflict));}
 let p=s.prepare_delete(&i,"delete",&l.date).unwrap();s.inject_sql_for_test("UPDATE cycle_day_logs SET notes='delete drift'").unwrap();assert_eq!(s.commit(&p),Err(Error::Conflict));
}
#[test]
fn settings_absence_race_and_identity_aba_rejected(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();let a=s.prepare_save(&i,"a",&l).unwrap();let mut second=l.clone();second.date="2024-03-18".into();let b=s.prepare_save(&i,"b",&second).unwrap();s.commit(&a).unwrap();assert_eq!(s.commit(&b),Err(Error::Conflict));let mut next=i.clone();next.session+=1;next.epoch+=1;s.transition_for_test(&next).unwrap();assert_eq!(s.commit(&a),Err(Error::Stale));let mut back=i.clone();back.epoch+=2;s.transition_for_test(&back).unwrap();assert_eq!(s.commit(&a),Err(Error::Stale));assert!(s.log(&second.date).unwrap().is_none());}
#[test]
fn unknown_reconciles_exact_receipt_delete_and_float_gate(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();let p=s.prepare_save(&i,"op",&l).unwrap();assert_eq!(s.commit_fault_for_test(&p,0,true).unwrap(),Outcome::Unknown);assert!(matches!(s.commit(&p).unwrap(),Outcome::Committed{replay:true,..}));let d=s.prepare_delete(&i,"delete",&l.date).unwrap();s.commit(&d).unwrap();assert!(s.log(&l.date).unwrap().is_none());assert!(matches!(s.commit(&d).unwrap(),Outcome::Committed{replay:true,..}));let mut n=l.clone();n.bbt_celsius=-0.0;let nz=s.prepare_save(&i,"negzero",&n).unwrap();s.commit(&nz).unwrap();assert_eq!(s.log(&n.date).unwrap().unwrap().bbt_celsius.to_bits(),0x80000000);}
#[test]
fn unsupported_existing_dates_reported_not_deleted(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();s.commit(&s.prepare_save(&i,"seed",&l).unwrap()).unwrap();s.inject_sql_for_test("UPDATE cycle_day_logs SET dateString='invalid-date'").unwrap();assert_eq!(s.unsupported_dates().unwrap(),vec!["invalid-date"]);assert!(s.log("invalid-date").unwrap().is_some());}
#[test]
fn every_full_field_oracle_row_roundtrips_or_fails_explicit_float_gate(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("fixtures/local_commit_track_oracle.json")).unwrap();let mut roundtrips=0;let signedzeros=0;
 for case in corpus["cases"].as_array().unwrap(){let p:serde_json::Value=serde_json::from_str(case["payload"].as_str().unwrap()).unwrap();let text=|k:&str|p[k].as_str().unwrap().to_string();let l=c::CycleDayLog{date:text("date"),flow:text("flow"),energy:text("energy"),mood:text("mood"),symptoms:text("symptoms"),vaginal_health:text("vaginal_health"),urinary_health:text("urinary_health"),cervical_mucus:text("cervical_mucus"),ovulation_test:text("ovulation_test"),bbt_celsius:p["bbt_celsius"].as_f64().unwrap() as f32,sleep_hours:p["sleep_hours"].as_f64().unwrap() as f32,sleep_quality:text("sleep_quality"),water_glasses:p["water_glasses"].as_i64().unwrap() as i32,notes:text("notes"),pain_intensity:p["pain_intensity"].as_i64().unwrap() as i32};let i=id();let s=ScratchStore::new_memory(&i).unwrap();let prepared=s.prepare_save(&i,"corpus",&l);

 s.commit(&prepared.unwrap()).unwrap();let read:c::CycleDayLog=(&s.log(&l.date).unwrap().unwrap()).into();assert_eq!(c::log_payload(&read),case["payload"].as_str().unwrap());assert_eq!(c::hash(Some(&c::log_payload(&read))),case["hash"].as_str().unwrap());roundtrips+=1;
 }assert_eq!(roundtrips+signedzeros,33);println!("Actual SQLite all-field roundtrips {roundtrips}; explicit signedzero refusals {signedzeros}");
}
#[test]
fn sidecar_preserves_both_signedzeros_and_detects_tamper(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let mut l=log();l.bbt_celsius=-0.0;l.sleep_hours=-0.0;s.commit(&s.prepare_save(&i,"zero",&l).unwrap()).unwrap();let read=s.log(&l.date).unwrap().unwrap();assert_eq!(read.bbt_celsius.to_bits(),0x80000000);assert_eq!(read.sleep_hours.to_bits(),0x80000000);let pending=s.prepare_save(&i,"pending",&l).unwrap();s.inject_sql_for_test("UPDATE local_float_bits SET bbt_bits=0").unwrap();assert_eq!(s.commit(&pending),Err(Error::Conflict));s.inject_sql_for_test("UPDATE local_float_bits SET bbt_bits=4294967296").unwrap();assert_eq!(s.log(&l.date),Err(Error::CorruptFloat));}
#[test]
fn external_update_invalidates_sidecar_never_resurrects_stale_sign(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let mut l=log();l.bbt_celsius=-0.0;s.commit(&s.prepare_save(&i,"zero",&l).unwrap()).unwrap();let p=s.prepare_save(&i,"old",&l).unwrap();s.inject_sql_for_test("UPDATE cycle_day_logs SET notes='external',bbtCelsius=0").unwrap();assert_eq!(s.commit(&p),Err(Error::Conflict));assert_eq!(s.log(&l.date).unwrap().unwrap().bbt_celsius.to_bits(),0);s.inject_sql_for_test("DELETE FROM cycle_day_logs").unwrap();assert!(s.log(&l.date).unwrap().is_none());}
#[test]
fn extended_dates_stored_exactly_with_anchor_overflow_failclosed(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();for (n,date) in ["-999999999-01-01","+10000-02-29","+999999999-12-31"].iter().enumerate(){let mut l=log();l.date=(*date).into();l.flow="LIGHT".into();let p=s.prepare_save(&i,&format!("x{n}"),&l).unwrap();s.commit(&p).unwrap();assert_eq!(s.log(date).unwrap().unwrap().date_string,*date);}assert!(s.unsupported_dates().unwrap().is_empty());let mut l=log();l.flow="LIGHT".into();assert_eq!(s.prepare_save(&i,"overflow",&l).unwrap_err(),Error::Plan(cyclecare_core::local_commit_plan::PlanError::Overflow));}
#[test]
fn sync_rows_and_nonwire_settings_preserved(){let i=id();let s=ScratchStore::new_memory(&i).unwrap();let mut l=log();s.commit(&s.prepare_save(&i,"seed",&l).unwrap()).unwrap();s.inject_sql_for_test("UPDATE cycle_settings SET isAppLockEnabled=1,lockTimeoutMinutes=5,remindPeriod=1,isOnboardingCompleted=1; INSERT INTO health_sync_revisions VALUES('existing','2024-03-17',7,'oldhash',0,123,5); INSERT INTO health_sync_outbox VALUES('existing','remote-op','2024-03-17','UPSERT',6,7,'payload','oldhash',3,2,99,'retry','server-ok',5);").unwrap();l.flow="LIGHT".into();let p=s.prepare_save(&i,"anchor",&l).unwrap();s.commit(&p).unwrap();let settings=s.settings().unwrap().unwrap();assert!(settings.is_app_lock_enabled&&settings.remind_period&&settings.is_onboarding_completed);assert_eq!(settings.lock_timeout_minutes,5);
 // SQL assertions execute only on scratch, fail transaction if any source row changed.
 s.inject_sql_for_test("CREATE TEMP TABLE assert_preserved(ok INTEGER CHECK(ok=1)); INSERT INTO assert_preserved SELECT COUNT(*) FROM health_sync_revisions WHERE ownerId='existing' AND revision=7 AND serverRevision=5 AND payloadHash='oldhash'; INSERT INTO assert_preserved SELECT COUNT(*) FROM health_sync_outbox WHERE ownerId='existing' AND operationId='remote-op' AND serverReceipt='server-ok' AND attempts=2 AND nextAttemptAt=99;").unwrap();}

#[test]
fn malformed_replay_receipt_never_becomes_success_or_rewrites_rows(){for raw in ["{}","[]","[5,\"Committed\",[]]","[6,\"Committed\",[]]","not-json"]{let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();let p=s.prepare_save(&i,"receipt-corrupt",&l).unwrap();s.commit(&p).unwrap();s.inject_sql_for_test(&format!("UPDATE local_receipts SET result='{}'",raw.replace('\'',"''"))).unwrap();assert_eq!(s.commit(&p),Err(Error::Storage));assert_eq!(c::log_payload(&c::CycleDayLog::from(&s.log(&l.date).unwrap().unwrap())),c::log_payload(&l));}}
#[test]
fn receipt_wrong_record_revision_hash_or_extra_entry_rejects_exact_replay(){for field in 0..4{let i=id();let s=ScratchStore::new_memory(&i).unwrap();let l=log();let p=s.prepare_save(&i,"receipt-fields",&l).unwrap();let Outcome::Committed{receipt,..}=s.commit(&p).unwrap()else{panic!()};let mut value:serde_json::Value=serde_json::from_str(&receipt).unwrap();match field{0=>value[2][0][0]="other-record".into(),1=>value[2][0][1]=999.into(),2=>value[2][0][2]="wrong-hash".into(),_=>value[2].as_array_mut().unwrap().push(serde_json::json!(["extra",1,"wrong-hash"]))};s.inject_sql_for_test(&format!("UPDATE local_receipts SET result='{}'",value.to_string().replace('\'',"''"))).unwrap();assert_eq!(s.commit(&p),Err(Error::Storage));}}
